import {createRequire} from 'node:module';
import {jest} from '@jest/globals';

const require = createRequire(import.meta.url);
jest.unstable_mockModule('ajv', () => ({default: require('ajv')}));

const {ToolRegistry} = await import('./registry.js');

describe('ToolRegistry module compatibility', () => {
  it('rejects enum input with a default-only validator export (specs/hal-engine-tool-input-validation/spec.md#11)', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registry.register(
      {
        name: 'weather',
        description: 'Forecast',
        inputSchema: {type: 'object', properties: {location: {enum: ['Berlin']}}},
      },
      execute
    );
    const response = await registry.execute('weather', {location: 'private-location'});
    expect({response, calls: execute.mock.calls}).toEqual({
      response: {result: 'data/location must be equal to one of the allowed values'},
      calls: [],
    });
  });
});
EOF
